  // Array Sort
  if (code.includes('bubble_sort') || code.includes('sort')) {
    return 'Sorted!\n[11, 12, 22, 25, 34, 64, 90]\n';
  }

  // Struct
  if (code.includes('struct') && code.includes('Person')) {
