   250→
   251→## 🚀 고급 예제
   252→
   253→### 7. 최단 경로 찾기 (BFS)
   254→
   255→```freelang
   256→struct Graph {
   257→  vertices: i64,
   258→  edges: i64[][]
   259→}
   260→
   261→fn bfs(graph: &Graph, start: i64, end: i64) -> i64[] {
   262→  let mut queue: i64[] = [start]
   263→  let mut visited: bool[] = []
   264→  let mut parent: i64[] = []
   265→
   266→  let mut i = 0
   267→  while i < graph.vertices {
   268→    visited.push(false)
   269→    parent.push(-1)
   270→    i = i + 1
   271→  }
   272→  visited[start] = true
   273→
   274→  while len(queue) > 0 {
   275→    let node = queue[0]
   276→
   277→    if node == end {
   278→      break
   279→    }
   280→
   281→    for neighbor in graph.edges[node] {
   282→      if !visited[neighbor] {
   283→        visited[neighbor] = true
   284→        parent[neighbor] = node
   285→        queue.push(neighbor)
   286→      }
   287→    }
   288→
   289→    queue = queue.slice(1, len(queue))
   290→  }
   291→
   292→  let mut path: i64[] = []
   293→  let mut current = end
   294→  while current != -1 {
   295→    path.push(current)
   296→    current = parent[current]
   297→  }
   298→  path.reverse()
   299→  return path
   300→}
   301→
   302→fn main() -> void {
   303→  // 예제 그래프 구성
   304→  // 0 -> 1, 2
   305→  // 1 -> 0, 3
   306→  // 2 -> 0, 3
   307→  // 3 -> 1, 2, 4
   308→  // 4 -> 3
   309→
   310→  println("BFS 경로 찾기 예제")
   311→}
   312→```
   313→
   314→### 8. 동적 프로그래밍 (배낭 문제)
   315→
   316→```freelang
   317→fn knapsack(weights: i64[], values: i64[], capacity: i64) -> i64 {
   318→  let n = len(weights)
   319→  let mut dp: i64[][] = []
   320→
   321→  let mut i = 0
   322→  while i <= n {
   323→    let mut row: i64[] = []
   324→    let mut j = 0
   325→    while j <= capacity {
   326→      row.push(0)
   327→      j = j + 1
   328→    }
   329→    dp.push(row)
   330→    i = i + 1
   331→  }
   332→
   333→  i = 1
   334→  while i <= n {
   335→    let mut j = 1
   336→    while j <= capacity {
   337→      if weights[i - 1] <= j {
   338→        let include = values[i - 1] + dp[i - 1][j - weights[i - 1]]
   339→        let exclude = dp[i - 1][j]
   340→        if include > exclude {
   341→          dp[i][j] = include
   342→        } else {
   343→          dp[i][j] = exclude
   344→        }
   345→      } else {
   346→        dp[i][j] = dp[i - 1][j]
   347→      }
   348→      j = j + 1
   349→    }
   350→    i = i + 1
   351→  }
   352→
   353→  return dp[n][capacity]
   354→}
   355→
   356→fn main() -> void {
   357→  let weights: i64[] = [2, 3, 4, 5]
   358→  let values: i64[] = [3, 4, 5, 6]
   359→  let capacity = 8
   360→
   361→  let max_value = knapsack(weights, values, capacity)
   362→  println("Maximum value: " + str(max_value))
   363→}
   364→```
