toolUseResult.content:
user nginx;
worker_processes auto;
error_log /var/log/nginx/error.log warn;
pid /var/run/nginx.pid;

events {
    worker_connections 1024;
    use epoll;
}

http {
    include /etc/nginx/mime.types;
    default_type application/octet-stream;

    log_format main '$remote_addr - $remote_user [$time_local] "$request" '
                    '$status $body_bytes_sent "$http_referer" '
                    '"$http_user_agent" "$http_x_forwarded_for"';

    access_log /var/log/nginx/access.log main;

    sendfile on;
    tcp_nopush on;
    tcp_nodelay on;
    keepalive_timeout 65;
    types_hash_max_size 2048;
    client_max_body_size 50m;

    gzip on;
    gzip_vary on;
    gzip_proxied any;
    gzip_comp_level 6;
    gzip_types text/plain text/css text/xml text/javascript
               application/json application/javascript application/xml+rss
               application/atom+xml image/svg+xml;

    # Rate limiting
    limit_req_zone $binary_remote_addr zone=api_limit:10m rate=100r/s;
    limit_req_zone $binary_remote_addr zone=general_limit:10m rate=10r/s;

    # ============ UPSTREAM SERVICES ============

    upstream bank_api {
        server bank-api:8080;
    }

    upstream bank_dashboard {
        server bank-dashboard:3000;
    }

    upstream playground_backend {
        server playground-backend:3000;
    }

    upstream playground_frontend {
        server playground-frontend:80;
    }

    upstream website {
        server website:80;
    }

    upstream prometheus {
        server prometheus:9090;
    }

    # ============ MAIN SERVER ============

    server {
        listen 80;
        listen [::]:80;
        server_name _;

        # -------- API Routes (Bank System) --------
        location /api/ {
            limit_req zone=api_limit burst=20 nodelay;

            proxy_pass http://bank_api/api/;
            proxy_http_version 1.1;
            proxy_set_header Upgrade $http_upgrade;
            proxy_set_header Connection 'upgrade';
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_cache_bypass $http_upgrade;

            # CORS Headers for API
            add_header 'Access-Control-Allow-Origin' '*' always;
            add_header 'Access-Control-Allow-Methods' 'GET, POST, PUT, DELETE, OPTIONS' always;
            add_header 'Access-Control-Allow-Headers' 'Content-Type, Authorization' always;
            add_header 'Access-Control-Max-Age' '86400' always;

            if ($request_method = 'OPTIONS') {
                return 204;
            }
        }

        # -------- Bank Dashboard --------
        location /dashboard {
            limit_req zone=general_limit burst=10 nodelay;

            rewrite ^/dashboard/?(.*)$ /$1 break;
            proxy_pass http://bank_dashboard;
            proxy_http_version 1.1;
            proxy_set_header Upgrade $http_upgrade;
            proxy_set_header Connection 'upgrade';
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_cache_bypass $http_upgrade;
        }

        # -------- Playground IDE --------
        location /playground {
            limit_req zone=general_limit burst=10 nodelay;

            rewrite ^/playground/?(.*)$ /$1 break;
            proxy_pass http://playground_frontend;
            proxy_http_version 1.1;
            proxy_set_header Upgrade $http_upgrade;
            proxy_set_header Connection 'upgrade';
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_cache_bypass $http_upgrade;
        }

        # -------- Prometheus Metrics (내부 접근만) --------
        location /metrics {
            # 내부 네트워크 + localhost만 허용
            allow 127.0.0.1;
            allow 172.16.0.0/12;  # Docker internal network
            deny all;

            proxy_pass http://prometheus;
            proxy_http_version 1.1;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_cache_bypass $http_upgrade;
        }

        # -------- Documentation & Website --------
        location /docs {
            limit_req zone=general_limit burst=10 nodelay;

            proxy_pass http://website/docs;
            proxy_http_version 1.1;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_cache_bypass $http_upgrade;
        }

        location /blog {
            limit_req zone=general_limit burst=10 nodelay;

            proxy_pass http://website/blog;
            proxy_http_version 1.1;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_cache_bypass $http_upgrade;
        }

        # -------- Health Check Endpoints --------
        location /health {
            access_log off;
            return 200 "healthy\n";
            add_header Content-Type text/plain;
        }

        # -------- Landing Page (Website) --------
        location / {
            limit_req zone=general_limit burst=10 nodelay;

            proxy_pass http://website;
            proxy_http_version 1.1;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_cache_bypass $http_upgrade;

            # Cache static assets
            expires 24h;
            add_header Cache-Control "public, immutable";
        }
    }
}
